command:
if (!game.user.isGM) {
  ui.notifications.warn("Apenas o mestre pode revelar handouts.");
  return;
}

const NOME_MACRO_JOGADOR = "Meus Handouts";

const PACKS_HANDOUTS = ["op2e-playtest.materiais-de-jogo"];
const ATOS = {
  "Ato I": {
    jornaisFonte: ["Handouts — Ato I"],
    journalMundo: "Handouts Revelados — Ato I"
  },
  "Ato II": {
    jornaisFonte: ["Handouts — Ato II"],
    journalMundo: "Handouts Revelados — Ato II"
  }
};

// 1) Pergunta qual Ato revelar primeiro -- cada ato tem sua própria lista de
//    handouts e seu próprio Journal de revelados no mundo, nunca se misturam.
const escolhaAto = await foundry.applications.api.DialogV2.input({
  window: { title: "Revelar Handout" },
  content: `<div class="form-group"><label>De qual Ato é o handout?</label><select name="ato" style="width:100%"><option value="Ato I">Ato I</option><option value="Ato II">Ato II</option></select></div>`,
  ok: { label: "Continuar" }
});
if (!escolhaAto) return;

const config = ATOS[escolhaAto.ato];

// 2) Junta todas as paginas de handout (tipo imagem) dos compendios de Materiais de Jogo,
//    filtrando apenas os journals-fonte do Ato escolhido.
let todasPaginas = [];
for (const packId of PACKS_HANDOUTS) {
  const pack = game.packs.get(packId);
  if (!pack) continue;
  const index = await pack.getIndex();
  const entradasHandouts = index.filter((e) => config.jornaisFonte.includes(e.name));
  for (const entrada of entradasHandouts) {
    const journal = await pack.getDocument(entrada._id);
    for (const pagina of journal.pages) {
      if (pagina.type === "image") todasPaginas.push(pagina);
    }
  }
}

if (!todasPaginas.length) {
  ui.notifications.warn(`Nenhum handout encontrado para o ${escolhaAto.ato} nos compêndios de Materiais de Jogo.`);
  return;
}

// 3) Acha (ou cria) o Journal do mundo daquele Ato especificamente, que fica visível
//    aos jogadores e onde os handouts revelados vao se acumulando -- diferente de
//    "Mostrar Imagem", que so aparece na hora e depois some, aqui fica salvo pra sempre.
let journalMundo = game.journal.getName(config.journalMundo);
if (!journalMundo) {
  journalMundo = await JournalEntry.create({
    name: config.journalMundo,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER }
  });
}

const jaRevelados = new Set(journalMundo.pages.map((p) => p.name));
const disponiveis = todasPaginas
  .filter((p) => !jaRevelados.has(p.name))
  .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));

if (!disponiveis.length) {
  ui.notifications.info(`Todos os handouts do ${escolhaAto.ato} já foram revelados aos jogadores.`);
  return;
}

const opcoes = disponiveis.map((p, i) => `<option value="${i}">${p.name}</option>`).join("");
const escolha = await foundry.applications.api.DialogV2.input({
  window: { title: `Revelar Handout — ${escolhaAto.ato}` },
  content: `<div class="form-group"><label>Qual handout revelar pros jogadores?</label><select name="idx" style="width:100%">${opcoes}</select></div>`,
  ok: { label: "Revelar" }
});
if (!escolha) return;

const paginaOriginal = disponiveis[Number(escolha.idx)];
const dadosPagina = paginaOriginal.toObject();
delete dadosPagina._id;
dadosPagina.ownership = { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER };

const [paginaNova] = await journalMundo.createEmbeddedDocuments("JournalEntryPage", [dadosPagina]);

// 4) Mostra o pop-up pra todo mundo na hora, alem de deixar salvo permanentemente no
//    Journal do Ato escolhido (visivel a qualquer jogador a partir de agora).
new foundry.applications.apps.ImagePopout({
  src: paginaNova.src,
  window: { title: paginaNova.name },
  uuid: paginaNova.uuid
}).shareImage();

// 5) Garante que todo jogador tenha um "livrinho" na hotbar (slot 3) pra abrir os handouts
//    revelados quando quiser, sem precisar caçar no Journal -- cria a macro na primeira vez
//    e fixa no slot 3 de cada jogador (sempre, pra cobrir jogador novo entrando depois). A
//    macro do jogador escolhe sozinha qual Ato mostrar (ou pergunta, se os dois tiverem
//    conteúdo).
let macroJogador = game.macros.getName(NOME_MACRO_JOGADOR);
if (!macroJogador) {
  macroJogador = await Macro.create({
    name: NOME_MACRO_JOGADOR,
    type: "script",
    img: "systems/op2e-playtest/assets/icones/meus-handouts.svg",
    scope: "global",
    command: "const NOMES_JOURNAL_MUNDO = {\n  \"Ato I\": \"Handouts Revelados — Ato I\",\n  \"Ato II\": \"Handouts Revelados — Ato II\"\n};\n\nconst comConteudo = Object.entries(NOMES_JOURNAL_MUNDO)\n  .map(([ato, nome]) => ({ ato, journal: game.journal.getName(nome) }))\n  .filter((e) => e.journal && e.journal.pages.size);\n\nif (!comConteudo.length) {\n  ui.notifications.info(\"Nenhum handout foi revelado ainda.\");\n  return;\n}\n\nif (comConteudo.length === 1) {\n  comConteudo[0].journal.sheet.render(true);\n  return;\n}\n\nconst escolha = await foundry.applications.api.DialogV2.wait({\n  window: { title: \"Meus Handouts\" },\n  content: \"<p>Qual ato você quer ver?</p>\",\n  buttons: comConteudo.map((e) => ({\n    action: e.ato,\n    label: e.ato,\n    callback: () => e.ato\n  }))\n});\nif (!escolha) return;\n\nconst alvo = comConteudo.find((e) => e.ato === escolha);\nalvo?.journal.sheet.render(true);\n",
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER }
  });
} else {
  await macroJogador.update({ command: "const NOMES_JOURNAL_MUNDO = {\n  \"Ato I\": \"Handouts Revelados — Ato I\",\n  \"Ato II\": \"Handouts Revelados — Ato II\"\n};\n\nconst comConteudo = Object.entries(NOMES_JOURNAL_MUNDO)\n  .map(([ato, nome]) => ({ ato, journal: game.journal.getName(nome) }))\n  .filter((e) => e.journal && e.journal.pages.size);\n\nif (!comConteudo.length) {\n  ui.notifications.info(\"Nenhum handout foi revelado ainda.\");\n  return;\n}\n\nif (comConteudo.length === 1) {\n  comConteudo[0].journal.sheet.render(true);\n  return;\n}\n\nconst escolha = await foundry.applications.api.DialogV2.wait({\n  window: { title: \"Meus Handouts\" },\n  content: \"<p>Qual ato você quer ver?</p>\",\n  buttons: comConteudo.map((e) => ({\n    action: e.ato,\n    label: e.ato,\n    callback: () => e.ato\n  }))\n});\nif (!escolha) return;\n\nconst alvo = comConteudo.find((e) => e.ato === escolha);\nalvo?.journal.sheet.render(true);\n" });
}
for (const jogador of game.users.filter((u) => !u.isGM)) {
  await jogador.update({ "hotbar.3": macroJogador.id });
}

ui.notifications.info(`Handout "${paginaNova.name}" (${escolhaAto.ato}) liberado! Já apareceu na tela dos jogadores e fica salvo no Journal "${config.journalMundo}" pra sempre.`);
